$(document).ready(function() {

    /**
     * BACKGROUND VIDEO
     * Source: https://github.com/VodkaBears/Vide
     */

    // Manually trigger play on load (fake "autoplay")
    // Ensures video plays automatically in Safari
    var home_video = $('[data-home-video]');
    if( home_video.length ) {

        var bgVideo = home_video.data("vide").getVideoObject();
        bgVideo.play();

        // Slight delay then fade, to allow the size calculations to take place (cheers IE)
        var timeout = 500;
        if(isIE()){
            timeout = 2000;
        }

        setTimeout(function(){
            home_video.removeClass('opacity-0');
        }, timeout);

    }


    /*======================================================
     NOTIFICATION
     ========================================================*/

    var notification = $("[data-notification]");

    // If no cookie is set, show the outdated message
    if(notification.length){
        if(Cookies.get('outdated-dismissed') == undefined) {
            notification.fadeIn();
        }
    }

    $(document).on( 'click', '[data-notification] [data-dismiss]', function(){

        $('[data-notification]').remove();
        headerSpace();

        Cookies.set('outdated-dismissed', '1', { expires: 7, path: '' });

    });


    /*======================================================
        MODALS
    ========================================================*/

    $('[data-video-modal]').magnificPopup({
        type: 'iframe',
        mainClass: "mfp-video-modal mfp-fade"
    });

    $('[data-resource-modal]').magnificPopup({
        type: 'iframe',
        mainClass: "mfp-page-modal mfp-fade",
        disableOn: 640
    });

    $('[data-resource-modal-internal]').magnificPopup({
        type: 'inline',
        mainClass: "mfp-resource-modal mfp-fade"
    });

    $('[data-package-modal]').magnificPopup({
        type: 'inline',
        showCloseBtn: false,
        mainClass: "mfp-resource-modal mfp-fade"
    });


    /*======================================================
        HEADER SPACE
    ========================================================*/

    var header = $('[data-header]');

    function headerSpace(){
        var headerHeight = header.outerHeight();
        $('[data-body]').css('padding-top', + headerHeight + "px");
    }

    if( header.length ) {

      headerSpace();

      $(window).resize(function(){
        headerSpace();
      });

    }

    /*======================================================
        RESOURCE MODAL FORMS
     ========================================================*/
    $(document).on( 'submit', '[data-resource-form]', function( evt ){
        evt.preventDefault();
        evt.stopPropagation();

        var $form = $(this);

        $.ajax({
            url: '/ajax/resource/form_submit',
            type: 'POST',
            data: {
                _token: $('meta[name="csrf-token"]').attr('content'),
                resource_id: $form.data('resource'),
                name: $form.find('[name="name"]').val(),
                email: $form.find('[name="email"]').val()
            },
            dataType: 'json',
            beforeSend: function(){
                $form.find('[data-error]').remove();
                $form.find('[data-generic-error]').hide();
            },
            success: function( json ){
                if( json.success ){
                    $form.find('[data-success]').show();
                    $form.find('[data-field-wrap]').hide();
                } else {
                    if( typeof( json.errors ) != 'undefined' ){
                        for( var field in json.errors ){
                            var error = json.errors[ field ];
                            var $field = $form.find('[data-field="' + field + '"]');

                            if( $field.length ){
                                $field.after( '<div data-error class="error">' + error + '</div>' );
                            } else {
                                $form.find('[data-generic-error]').show();
                            }
                        }
                    } else {
                        $form.find('[data-generic-error]').show();
                    }
                }
            }
        });

        return false;
    });


    /*======================================================
        GOOGLE ANALYTICS
    ========================================================*/

    $(document).on( 'click', '[data-ga-event]', function(){
        if( typeof( gtag ) != 'undefined' ){
            var category = $(this).data('ga-category');
            var action = $(this).data('ga-action');
            var label = $(this).data('ga-label');
            var value = $(this).data('ga-value');

            // Ensure that all variables are unified in casing.
            category = typeof( category ) == 'string' ? category : category;
            action = typeof( action ) == 'string' ? action : action;
            label = typeof( label ) == 'string' ? label : label;
            value = typeof( value ) == 'string' ? value : value;

            if( typeof( category ) != 'undefined' && typeof( action ) != 'undefined' ){
                var event_settings = {
                    event_category: category
                };
                if( typeof( label ) != 'undefined' ){
                    event_settings.event_label = label;
                }
                if( typeof( value ) != 'undefined' ){
                    event_settings.value = value;
                }

                gtag( 'event', action, event_settings );
            }
        }
    });

}); // END DOC READY


/**
 * DETECT INTERNET EXPLORER
 * Source: https://stackoverflow.com/questions/49986720/how-to-detect-internet-explorer-11-and-below-versions
 */
function isIE() {
    var ua = window.navigator.userAgent; //Check the userAgent property of the window.navigator object
    var msie = ua.indexOf('MSIE '); // IE 10 or older
    var trident = ua.indexOf('Trident/'); //IE 11
    return (msie > 0 || trident > 0);
}